using System;using System.Diagnostics;using System.IO;using System.Net;using System.Net.Sockets;using System.Reflection;using System.Text;using System.Threading;
namespace PZ3D {static class FeedbackDeadlineTests {
 public static int Main(){var type=typeof(Engine).Assembly.GetType("PZ3D.FeedbackUpload");if(type==null){Console.WriteLine("FAIL whole feedback upload must have a bounded deadline including receipt body reads");return 1;}var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;var worker=new Thread(()=>{try{using(var client=listener.AcceptTcpClient())using(var stream=client.GetStream()){stream.ReadTimeout=1000;stream.WriteTimeout=1000;string header="";int n;while(header.Length<8192&&!header.EndsWith("\r\n\r\n")&&(n=stream.ReadByte())>=0)header+=(char)n;stream.ReadByte();stream.ReadByte();byte[] response=Encoding.ASCII.GetBytes("HTTP/1.1 201 Created\r\nContent-Type: application/json\r\nContent-Length: 10000\r\nConnection: close\r\n\r\n");stream.Write(response,0,response.Length);for(int i=0;i<30;i++){stream.WriteByte(32);stream.Flush();Thread.Sleep(80);}}}catch{}});worker.IsBackground=true;worker.Start();try{var request=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:"+port+"/");request.Method="POST";request.ContentLength=2;request.Proxy=null;request.ServicePoint.Expect100Continue=false;var watch=Stopwatch.StartNew();bool failed=false;try{type.GetMethod("Send",BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).Invoke(null,new object[]{request,Encoding.UTF8.GetBytes("{}"),CancellationToken.None,250});}catch(TargetInvocationException){failed=true;}if(!failed||watch.ElapsedMilliseconds>2000)throw new Exception("dripping reply outlived whole-upload deadline");Console.WriteLine("PASS actual slow HTTP reply aborted by whole-upload deadline at "+watch.ElapsedMilliseconds+"ms");return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}finally{listener.Stop();worker.Join(3000);}}
}}
